-- 1. Disable Row-Level Security (RLS) on medicines and pharmacies tables
ALTER TABLE IF EXISTS public.medicines DISABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.pharmacies DISABLE ROW LEVEL SECURITY;

-- 2. Add extra fields to medicines table if missing
ALTER TABLE IF EXISTS public.medicines ADD COLUMN IF NOT EXISTS form text;
ALTER TABLE IF EXISTS public.medicines ADD COLUMN IF NOT EXISTS strength text;
ALTER TABLE IF EXISTS public.medicines ADD COLUMN IF NOT EXISTS manufacturer text;

